# -*- coding: utf-8 -*-
from data import a
PR=lambda t: a(t,'rs'); ZK=lambda t: a(t,'zpi')
RS={}

RS['01-strategiya']=[('Что это',['**Предварительные работы** (чл. 112 Закона): исследования, анализы и проекты; данные по инженерно-геологическим, геотехническим, геодезическим, гидрологическим, метеорологическим, урбанистическим, техническим, технологическим, экономическим, энергетическим, сейсмическим, водохозяйственным и транспортным условиям; условия защиты от пожара и среды.','**Предварительная студия оправданности** (*prethodna studija opravdanosti*) — оценка пространственной, экологической, социальной, финансовой, рыночной и экономической обоснованности инвестиции для вариантных решений, определённых генеральным проектом; содержит GNP (чл. 113 Закона).','**Студия оправданности** (*studija opravdanosti*) — то же для выбранного решения, разработанного идейным проектом; для проектов с участием публичных средств (чл. 114 Закона).']),
 ('Генеральный проект (GNP)',['цель: оценить ресурсные и пространственные возможности и ограничения, принять генеральную концепцию, макролокацию и пространственную диспозицию, определить основные функциональные, технологические и технические характеристики, этапность, условия эксплуатации, отношение к среде, основу экономического анализа (чл. 14 Правилника);','содержит макролокацию, общую диспозицию, технико-технологическую концепцию, обеспечение инфраструктурой, возможные варианты пространственных и технических решений, природные условия, оценку влияния на среду и др. (чл. 117 Закона, чл. 34 Правилника);','при нескольких вариантах выбирается оптимальный по природным, техническим, технологическим, экономическим, функциональным и экологическим условиям.']),
 ('Документы и контроль',['GNP подлежит ревизии (профессиональной проверке) комиссией, если объект относится к чл. 133 Закона (чл. 131 Закона).']),
 ('Детализация',['графика GNP для линейных объектов — масштаб 1:25000–1:10000 или другой удобный (чл. 34 Правилника).']),
 ('Источники',[PR('Правилник 96/2023, чл. 2, 14, 34'),ZK('Закон, чл. 112–117, 131')])]

RS['02-zadanie']=[('Что это',['**Локационные условия** (*lokacijski uslovi*) содержат все урбанистические, технические и иные условия и данные для разработки IDP, PGD и PZI; выдаются на кадастровый участок, отвечающий условиям строительного участка (чл. 53а Закона). Идейное решение (IDR) — основа для их выдачи (чл. 15 Правилника).','**Информация о локации** (*informacija o lokaciji*) — сведения о возможностях и ограничениях строительства по плану; выдаётся в течение 8 дней (чл. 53 Закона).']),
 ('Порядок и сроки',['орган обязан выдать локационные условия в течение 5 рабочих дней после получения всех условий и данных от держателей публичных полномочий (чл. 56, 8д Закона);','всю процедуру от локационных условий до разрешения на использование ведёт единая «объединённая процедура» в электронной форме (чл. 8, 8а Закона); орган проверяет только формальные условия и не оценивает техническую документацию (чл. 8đ).']),
 ('Исходные данные для проекта',['геодезические и сейсмологические основы, геотехнический элаборат и иные основы — по виду и классу объекта (чл. 22 Правилника).']),
 ('Источники',[ZK('Закон, чл. 8–8đ, 53, 53а, 55, 56'),PR('Правилник 96/2023, чл. 15, 22')])]

RS['03-koncepciya']=[('Что это',['**Идейное решение (IDR)** — показ планируемой концепции объекта с данными, необходимыми для локационных условий и проверки соответствия плану: назначение, БРГП, габарит, регуляция, положение на участке, доступ, число функциональных единиц, мощности и подключение (чл. 15 Правилника). Разработка технических решений не требуется (чл. 117а Закона).','IDR — составная часть локационных условий только в части существенных элементов; остальные детали необязательны для дальнейшей проработки.']),
 ('Состав (чл. 35–41)',['главная книга: основное содержание по Приложению 1 и сжатый технический описание существующего и планируемого состояния (Приложение 1А), подписанный главным проектантом; при изменении локационных условий — описание изменений;','для зданий обязательна часть «архитектура»; отдельным документом — перечень всех кадастровых участков, подписанный главным проектантом;','текст: технический описание с коммунальными мощностями; при сносе — описание существующего состояния;','числа: площади по назначениям и число функциональных единиц;','elaborati и studije не прилагаются (кроме гидрологической студии, когда нужна).']),
 ('Детализация (чл. 40)',['ситуационный план (положение, габарит, размеры, отметки, расстояния до соседних участков и объектов, сводный план инсталляций на участке) — 1:1000–1:200;','планы, характерные разрезы, фасады — 1:500–1:100, с делением на функциональные единицы и общие помещения, **без обязанности показывать внутреннюю планировку внутри функциональных единиц и проставлять в них размеры**;','геодезическая основа — без обязательной заверки.']),
 ('Оформление',['на каждом чертеже в нижнем правом углу — штамп не шире 18 см: инвестор, объект, организация, вид документации (IDR, IDP, PGD, PZI, PIO), название части, чертежа, масштаб, главный проектант и номер лицензии, номер чертежа, дата; легенда и знак севера (чл. 31).']),
 ('Источники',[PR('Правилник 96/2023, чл. 15, 31, 35–41'),ZK('Закон, чл. 117а')])]

RS['04-eskiz']=[('Что это',['**Идейный проект (IDP)** — проект или совокупность согласованных проектов, определяющих назначение, положение, форму, мощность, технико-технологические и функциональные характеристики и вид объекта, описывающих работы и доказывающих выполнение основных требований — по виду и классу объекта и работ (чл. 16 Правилника).','Нужен для реконструкции и работ по чл. 145 Закона (решение об одобрении работ) и для объектов по чл. 133 Закона (подлежит профессиональной проверке комиссией) (чл. 118 Закона); для таких объектов IDP подлежит технической проверке (чл. 118, ст. 3 Закона).']),
 ('Состав (чл. 42–49)',['главная книга: решение о главном проектанте, заявление главного проектанта о согласованности частей, сжатый технический описание;','текст: технический описание, описание материалов, инсталляций и оборудования, перечень работ; при реконструкции — оценка несущей способности существующей конструкции;','числа: таблицы площадей по помещениям и этажам, расчёты главных элементов конструкций, общие расчёты инсталляций, оценка потребления;','elaborati и studije — при работах, влияющих на основные требования (например, энергоэффективность, пожарная безопасность), и исследование влияния на среду, если оно нужно (чл. 49).']),
 ('Детализация (чл. 47)',['архитектура: ситуационный план 1:500–1:200 на геодезической основе, план фундамента, планы всех этажей с размерами и отметками, план крыши, два взаимно перпендикулярных разреза, фасады — 1:200–1:100;','конструкции: диспозиционные чертежи, планы с позициями и размерами главных элементов;','инсталляции: основные схемы и подключение к инфраструктуре;','геодезическая основа — топографический снимок, интегрированный с кадастровым планом, от лицензированной геодезической организации.']),
 ('Источники',[PR('Правилник 96/2023, чл. 16, 42–49'),ZK('Закон, чл. 118, 131')])]

RS['05-ago-agr']=[('Аналог',['В прочитанных Законе и Правилнике (ред. до 80/2026 и 96/2023) отдельной стадии согласования облика нет: требования к форме и габариту задают планы и локационные условия, а проверка проекта — техническая контроль (чл. 80 Правилника) ⏳. Местные процедуры (например, в Белграде) не читались.']),
 ('Источники',[PR('Правилник 96/2023'),ZK('Закон о планировании и строительстве')])]

RS['06-proekt-razresheniya']=[('Что это',['**Проект для разрешения на строительство (PGD)** — совокупность согласованных проектов: положение и мощность объекта, функциональность по технологическим и иным требованиям, объёмное оформление, выбор конструктивной системы, размеры главных элементов, выбор строительных изделий и требуемые характеристики, инсталляции и оборудование; обеспечивает выполнение локационных условий и основных требований (чл. 17 Правилника; чл. 118а Закона). Содержит заявления главного проектанта, ответственного проектанта и исполнителя технической проверки (чл. 118а Закона).']),
 ('Состав по категориям (чл. 52)',['категория **A**: проект архитектуры с заявлением о выполнении требования «механическая стойкость и устойчивость»;','категория **B**: архитектура, конструкции, технические описания инсталляций;','категория **V**: архитектура, конструкции, инсталляции и проекты всех относящихся областей;','категория **G**: проекты соответствующих областей;','для объектов по чл. 133 Закона любой категории — все относящиеся проекты.','Нумерация частей (чл. 26): 1 — архитектура; 2 — строительные проекты; 3 — гидротехнические инсталляции; 4 — электроэнергетика; 5 — связь и сигнализация; 6 — машинные инсталляции; 7 — технология; 8 — транспорт; 9 — внешнее благоустройство и сводный план инсталляций; 10 — подготовительные работы.']),
 ('Главная книга и документы (чл. 51, 53–57)',['главная книга: решение о главном проектанте, заявление о согласованности частей, сжатый технический описание, условия, полученные вне объединённой процедуры;','текст: описание участка, климата и сейсмики, предварительных исследований, соответствия локационным условиям, формы и функций, конструкции и фундаментов, требуемых характеристик строительных изделий, инсталляций, этапности, мер по основным требованиям;','числа: таблицы площадей по помещениям и этажам с назначением и числом функциональных единиц; расчёты, доказывающие механическую стойкость, часть требований по пожарной безопасности и др.; оценка стоимости работ;','прилагаются (по виду и классу): геотехнический elaborat, elaborat защиты от пожара (если нужен главный проект защиты от пожара), elaborat энергоэффективности, исследование влияния на среду; elaborati технической проверке не подлежат — проверяется применение предусмотренных ими мер.']),
 ('Детализация (чл. 56)',['архитектура: ситуационный план 1:500–1:200 на геодезической основе, план фундамента, планы всех этажей с размерами и отметками, план крыши, два взаимно перпендикулярных и другие разрезы, фасады — 1:200–1:100;','конструкции: диспозиция конструкции, детальный план позиций и размеры всех элементов главной несущей конструкции, узлы и схемы опор;','инсталляции: основные схемы с точками подключения на объекте и на существующей инфраструктуре на участке;','внешнее благоустройство: ситуационно-нивелировочный план 1:500–1:200.']),
 ('Для разрешения',['к заявлению прилагаются PGD и **выписка из проекта** (*izvod iz projekta*): титульный лист с заверкой главного проектанта, заявление исполнителя технической проверки с резюме отчёта и главная книга PGD (чл. 33 Правилника).','Другие виды: изменённый PGD или приложение изменений (чл. 58), проект сноса (чл. 59), проект подготовительных работ (чл. 60; для особого разрешения на подготовительные работы, например при БРГП более 800 м², чл. 137 Закона).']),
 ('Форма',['документация изготавливается в электронной форме и подписывается квалифицированной электронной подписью; на сербском языке (чл. 20 Правилника).']),
 ('Источники',[PR('Правилник 96/2023, чл. 17, 20, 26, 31, 33, 51–60'),ZK('Закон, чл. 118а, 137')])]

RS['07-ekspertiza']=[('Что это',['**Техническая проверка** (*tehnička kontrola*) — проверка проекта для разрешения на строительство (чл. 129 Закона; чл. 79 Правилника); проверке также подлежат проект сноса и проект подготовительных работ с элементами конструкций, а также IDP для реконструкции линейных объектов.','Elaborati и studije проверке не подлежат; проверяется, применены ли предусмотренные ими меры. Технические описания инсталляций объектов категории B не проверяются отдельно (чл. 79).']),
 ('Что проверяется (чл. 80)',['соответствие локационным условиям и условиям держателей публичных полномочий;','соответствие законам, техническим нормам, стандартам;','полнота частей и взаимная согласованность;','правильность применения результатов предварительных и изыскательских работ;','обеспечение основных требований к объекту, в том числе применение мер из elaborati и studije.']),
 ('Документы',['отчёт о технической проверке (чл. 82), окончательный отчёт после устранения замечаний (чл. 83), заявление исполнителя проверки с резюме отчёта (приложение 5) в выписке из проекта (чл. 84); на каждой части проекта — «Проект принимается» (чл. 85).','Проект, выполненный по нормам другой страны, проверяется на переводе на сербский язык (чл. 86).']),
 ('Ревизия',['GNP и IDP, предварительная и полная studija opravdanosti для объектов по чл. 133 Закона проходят ревизию комиссии министра (чл. 131 Закона); техническая проверка PGD таких объектов включает проверку выполнения мер из отчёта комиссии (чл. 81 Правилника).']),
 ('Отличие от России',['орган выдачи разрешения в объединённой процедуре проверяет только формальные условия и не оценивает техническую документацию (чл. 8đ Закона); оценку содержания делает исполнитель технической проверки — лицензированная организация, выбранная инвестором.']),
 ('Источники',[PR('Правилник 96/2023, чл. 79–86'),ZK('Закон, чл. 8đ, 129, 131')])]

RS['08-razreshenie']=[('Что это',['**Разрешение на строительство** (*građevinska dozvola*) выдаётся инвестору, который с заявлением подаёт PGD и выписку из проекта; решение о согласии на План управления отходами от строительства и сноса; доказательство права на земельный участок или объект; доказательства оплаты сборов и иные доказательства, предусмотренные правилами объединённой процедуры; заявление инвестора и ответственного проектанта о соответствии мерам защиты окружающей среды (чл. 135 Закона).']),
 ('Сроки',['5 рабочих дней со дня подачи заявления (чл. 8д Закона).']),
 ('Действие',['разрешение выдаётся на весь объект или на часть, представляющую техническую и функциональную единицу (чл. 137); подготовительные работы могут выполняться по этому разрешению, а для объектов по чл. 133 и объектов более 800 м² БРГП — и по особому;','к строительству приступают на основании вступившего в силу решения и *prijava radova* (при конечном решении — на риск инвестора) (чл. 138а);','разрешение утрачивает силу, если в течение 3 лет со вступления в силу не подана prijava radova, и если в течение 5 лет не выдано разрешение на использование (с исключениями) (чл. 140).']),
 ('Источники',[ZK('Закон, чл. 8д, 135–140')])]

RS['09-rabochaya']=[('Что это',['**Проект для производства работ (PZI)** — совокупность проектов, необходимых для строительных, ремесленных, инсталляционных и других работ; определяет строительно-технические, технологические и эксплуатационные характеристики с оборудованием и инсталляциями, способ контроля и обеспечения качества строительных изделий, организационные решения, инвестиционную стоимость и условия обслуживания (чл. 18 Правилника, чл. 123 Закона). Обязателен для объектов с разрешением, кроме категории «A».']),
 ('Состав (чл. 61–70)',['главная книга: решение о главном проектанте, заявление о согласованности, копии согласий, сжатый технический описание (чл. 61);','текст: дополнительные характеристики материалов и оборудования, места и способы установки, конструктивная система, методики работ, испытания и измерения (чл. 64);','числа: дополнительные расчёты конструкций и узлов, подбор инсталляций и оборудования, потребление энергии; спецификации и обмеры — при необходимости (чл. 65);','прилагаются: **План превентивных мер** по охране труда на стройплощадке (чл. 67); **Программа контроля и обеспечения качества** — перечень и характеристики всех изделий и сборных элементов, описание испытаний и требуемых результатов, пробной эксплуатации, периодических осмотров (чл. 68); при необходимости — проект геодезической разбивки и проект наблюдения за поведением грунта и объекта (чл. 69);','PZI должен быть согласован с главным проектом защиты от пожара (чл. 70).']),
 ('Детализация (чл. 66)',['чертежи, схемы и детали строительных, ремесленных и инсталляционных работ; сводные планы инсталляций; инструкции по установке; технологические схемы; чертежи земляных работ и креплений котлована; детальные конструктивные чертежи с позициями всех элементов, планы опалубки и арматуры, узлы и стыки; изоляция; схемы этапности; приключения;','масштаб — соответствующий строительству; PZI может разрабатываться по частям и этапам, и работы ведутся только для утверждённой части (чл. 123 Закона).']),
 ('Источники',[PR('Правилник 96/2023, чл. 18, 61–70'),ZK('Закон, чл. 123')])]

RS['10-stroitelstvo']=[('Начало работ',['инвестор подаёт **prijava radova** органу, выдавшему разрешение, до начала работ; с ней: доказательство уплаты взносов на обустройство земли, сбор, полис страхования ответственности перед третьими лицами и др.; подтверждение — немедленно, а при обеспечительных средствах — в течение 5 рабочих дней (чл. 148, 8д Закона);','до начала инвестор обеспечивает разбивку участка и линий и табличку на стройплощадке (объект, инвестор, проектант, номер разрешения, подрядчик, сроки) (чл. 149).']),
 ('Участники',['подрядчик (*izvođač radova*) — лицензированный, перед началом подписывает PZI и назначает ответственного производителя работ на площадке (чл. 150–152);','**стручный надзор** — обеспечивает инвестор: контроль соответствия разрешению и документации, качества работ, нормативов, испытаний и количеств, документов на изделия; сотрудничество с проектантом (чл. 153).']),
 ('Этапные уведомления',['*prijava završetka izgradnje temelja* и *prijava završetka izgradnje objekta u konstruktivnom smislu* принимаются немедленно при наличии документации (чл. 8д, п. 3а–3б).']),
 ('Источники',[ZK('Закон, чл. 8д, 148–153')])]

RS['11-ispolnitelnaya']=[('Что это',['**Проект построенного объекта (PIO)** — совокупность проектов с показом всех деталей построенного объекта, нужных для определения пригодности к использованию; разрабатывается для получения разрешения на использование, эксплуатации и обслуживания; нужен для всех объектов с разрешением на строительство (чл. 19 Правилника, чл. 124 Закона). Это PZI с изменениями, возникшими при строительстве.']),
 ('Состав (чл. 71–78)',['если отступлений от PZI не было — к главной книге IO прилагается PZI с констатацией соответствия; инвестор, надзор и подрядчик подтверждают на PZI, что построенное равно запроектированному (чл. 71; чл. 124 Закона);','если отступления есть, но не противоречат локационным условиям и разрешению и не требуют изменения разрешения (чл. 142 ст. 2 Закона) — PIO для изменившихся частей, подробное описание изменений и перечень листов (чл. 71–72);','общая, текстовая и числовая документация — по тем же правилам, с описанием изменений (чл. 73–75); графика по чл. 31 (чл. 76);','с PIO прилагаются Программа контроля качества и проект наблюдения (чл. 77);','для категории «A» без PZI вместо PIO допускается геодезическая съёмка построенного объекта (чл. 78).']),
 ('Контроль',['PIO технической проверке не подлежит, кроме случаев легализации объекта (чл. 124 Закона).']),
 ('Источники',[PR('Правилник 96/2023, чл. 19, 71–78'),ZK('Закон, чл. 124')])]

RS['12-priemka-vvod']=[('Что это',['**Технический осмотр** (*tehnički pregled*) определяет пригодность объекта к использованию: проверка соответствия работ разрешению и технической документации, техническим нормам и стандартам (чл. 154 Закона). Проводится по окончании строительства объекта или части, образующей техническую и технологическую единицу; возможен и параллельно с работами.','Комиссию формирует инвестор; при особых мерах пожарной защиты в комиссию входит инженер по защите от пожара с лицензией (чл. 155). При необходимости комиссия допускает пробную эксплуатацию (чл. 157).']),
 ('Разрешение на использование',['**Upotrebna dozvola** выдаётся органом, выдавшим разрешение на строительство, в течение 5 рабочих дней со дня подачи заявления (чл. 158, 8д Закона); на основании вступившего в силу разрешения и prijava radova, возможно на риск инвестора и по конечному решению.','К заявлению прилагаются: отчёт комиссии о пригодности; PIO либо PZI с заявлением надзора, подрядчика и инвестора об отсутствии отступлений; спецификация особых частей; решение о номере дома; геодезический элаборат построенного объекта и подземных инсталляций; сертификат энергетических свойств, если нужен; документ о движении строительных отходов; иные доказательства.']),
 ('Источники',[ZK('Закон, чл. 8д, 154–158'),PR('Правилник 96/2023, чл. 19')])]

RS['13-peredacha']=[('Что это',['В Законе и Правилнике отдельной стадии передачи объекта заказчику нет; она оформляется договором. Разрешение на использование (upotrebna dozvola) — юридический рубеж между строительством и эксплуатацией ⏳.']),
 ('Источники',[ZK('Закон, чл. 158'),PR('Правилник 96/2023')])]

RS['14-ekspluatatsiya']=[('Что это',['Владелец объекта, на который выдано разрешение на использование, обеспечивает инвестиционное и текущее обслуживание объекта, а также регулярные, чрезвычайные и специализированные осмотры в соответствии со специальными нормами (чл. 159 Закона).','PIO используется для эксплуатации и обслуживания (чл. 19 Правилника).']),
 ('Не сверено',['конкретные специальные нормы по осмотрам не читались ⏳.']),
 ('Источники',[ZK('Закон, чл. 159'),PR('Правилник 96/2023, чл. 19')])]
